import{_ as t,o as e,c as i,a2 as l}from"./chunks/framework.BW2T23B9.js";const u=JSON.parse('{"title":"AI 工作流","description":"所有 LLM 请求经过统一 AI 引擎。领域模块构造 Prompt、解析结果并执行本地校验。AI 输出不是直接可执行状态。","frontmatter":{"description":"所有 LLM 请求经过统一 AI 引擎。领域模块构造 Prompt、解析结果并执行本地校验。AI 输出不是直接可执行状态。"},"headers":[],"relativePath":"guide/ai-workflows.md","filePath":"guide/ai-workflows.md","lastUpdated":1787830168000}'),d={name:"guide/ai-workflows.md"};function r(s,a,n,o,p,h){return e(),i("div",null,[...a[0]||(a[0]=[l(`<h1 id="ai-工作流" tabindex="-1">AI 工作流 <a class="header-anchor" href="#ai-工作流" aria-label="Permalink to &quot;AI 工作流&quot;">​</a></h1><p>所有 LLM 请求经过统一 AI 引擎。领域模块构造 Prompt、解析结果并执行本地校验。AI 输出不是直接可执行状态。</p><h2 id="功能矩阵" tabindex="-1">功能矩阵 <a class="header-anchor" href="#功能矩阵" aria-label="Permalink to &quot;功能矩阵&quot;">​</a></h2><table tabindex="0"><thead><tr><th>工作流</th><th>输入</th><th>输出</th><th>写入边界</th></tr></thead><tbody><tr><td>提示助手</td><td>当前题目与允许的课程上下文</td><td>分层提示</td><td>会话与学习证据</td></tr><tr><td>深度讲解</td><td>句子、语法点或错误</td><td>结构化解释</td><td>可选知识笔记</td></tr><tr><td>SRS 导师</td><td>错题、弱词、近期复习</td><td>临时复习课</td><td>校验后进入课程流程</td></tr><tr><td>许愿生成</td><td>多轮需求、附件</td><td>Section JSON 草稿</td><td>人工确认后写入</td></tr><tr><td>教材导入</td><td>文本章节与预设</td><td>资源和课时草稿</td><td>审校、合并后写入</td></tr><tr><td>Lesson 助手</td><td>当前 Lesson</td><td>修改建议或内容</td><td>经 schema 校验后应用</td></tr></tbody></table><h2 id="分层提示状态机" tabindex="-1">分层提示状态机 <a class="header-anchor" href="#分层提示状态机" aria-label="Permalink to &quot;分层提示状态机&quot;">​</a></h2><p>提示按固定顺序升级：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>conceptCue</span></span>
<span class="line"><span>  -&gt; ruleCue</span></span>
<span class="line"><span>  -&gt; contrastCue</span></span>
<span class="line"><span>  -&gt; partialReveal</span></span>
<span class="line"><span>  -&gt; fullExplain</span></span>
<span class="line"><span>  -&gt; verify</span></span></code></pre></div><p>模型不得自行跳过状态。状态机由本地逻辑控制。这样可以避免首次请求直接泄露完整答案。</p><h2 id="课程检索" tabindex="-1">课程检索 <a class="header-anchor" href="#课程检索" aria-label="Permalink to &quot;课程检索&quot;">​</a></h2><p>检索器只返回经过白名单校验的课程来源，并限制 Top-K。未配置模型时，仍可将本地片段作为确定性答疑材料。引用不存在或不属于当前课程时，不进入 Prompt。</p><h2 id="学习者画像" tabindex="-1">学习者画像 <a class="header-anchor" href="#学习者画像" aria-label="Permalink to &quot;学习者画像&quot;">​</a></h2><p><code>LearnerProfileSnapshot</code> 从本地证据生成最小摘要。关闭个性化后：</p><ul><li>不发送画像。</li><li>不发送旧会话摘要。</li><li>不发送错题历史。</li><li>当前用户主动输入仍按本次请求发送。</li></ul><h2 id="结构化输出" tabindex="-1">结构化输出 <a class="header-anchor" href="#结构化输出" aria-label="Permalink to &quot;结构化输出&quot;">​</a></h2><p>AI 生成课程或题目时执行以下门禁：</p><ol><li>解析 JSON。</li><li>应用 schema。</li><li>修复允许自动修复的 ID 冲突或引用断裂。</li><li>运行课程 validator。</li><li>显示 diff 或预览。</li><li>等待用户确认。</li><li>写入 JSON 真理源。</li></ol><p>无法解析的输出不做部分写入。</p><h2 id="会话数据" tabindex="-1">会话数据 <a class="header-anchor" href="#会话数据" aria-label="Permalink to &quot;会话数据&quot;">​</a></h2><p>原生平台可保存会话、消息、诊断、计划、笔记和请求指标。会话支持恢复、重命名、删除和纯文本导出。历史过长时使用摘要裁剪，不无上限拼接原始消息。</p><h2 id="明确不提供" tabindex="-1">明确不提供 <a class="header-anchor" href="#明确不提供" aria-label="Permalink to &quot;明确不提供&quot;">​</a></h2><ul><li>未经可靠模型验证的口音分数或音素分数。</li><li>在用户不知情时上传完整学习数据库。</li><li>让远端模型直接写 SQLite。</li><li>绕过课程校验器的自动发布。</li></ul><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="/docs/guide/ai-configuration">配置 AI</a></li><li><a href="/docs/guide/mistakes-and-weak-items">错题与弱项</a></li><li><a href="/docs/authoring/textbook-import">教材导入</a></li></ul>`,23)])])}const f=t(d,[["render",r]]);export{u as __pageData,f as default};
